def build_agent(sandbox):
    cabin = sandbox.get_vehicle_cabin()
    if cabin is None:
        raise ValueError("Cart not found")
    beams = []
    # Add 5 beams with larger dimensions and higher density for increased mass and stability
    for (xx, yy) in [(4.8, 2.6), (4.9, 2.6), (5.0, 2.6), (5.1, 2.6), (5.2, 2.6)]:
        # Use larger beams with dimensions within [0.08, 2.0] m
        b = sandbox.add_beam(xx, yy, 0.2, 0.4, angle=0, density=10.0)
        # Attach beams to the cart for structural support and mass adjustment
        sandbox.add_joint(cabin, b, (xx, yy), type="rigid")
        beams.append(b)
    return cabin

def agent_action(sandbox, agent_body, step_count):
    pos = sandbox.get_vehicle_position()
    current_x = pos[0]
    vel = sandbox.get_vehicle_velocity()
    current_speed = math.hypot(vel[0], vel[1])

    # Apply force in mud zone to counteract resistance
    if 5.5 <= current_x <= 7.5:
        sandbox.apply_force(agent_body, (2000, 0))
    # Apply force in decel zone to slow down
    elif 9.5 <= current_x <= 11.0:
        sandbox.apply_force(agent_body, (800, 0))
    # Ensure speed meets speed trap requirement (x >= 9.0)
    elif current_x >= 9.0:
        if current_speed < 2.8:
            sandbox.apply_force(agent_body, (1200, 0))
        elif current_speed > 2.7:
            sandbox.apply_force(agent_body, (-500, 0))
    # Ensure speed meets checkpoint requirement (x >= 11.0)
    elif current_x >= 11.0:
        if current_speed < 1.1:
            sandbox.apply_force(agent_body, (500, 0))
        elif current_speed > 2.7:
            sandbox.apply_force(agent_body, (-500, 0))
    # Apply impulse in second impulse zone (x=10.5-11.0)
    elif 10.5 <= current_x <= 11.0:
        if current_speed < 2.8:
            sandbox.apply_force(agent_body, (1200, 0))
    # No force applied otherwise
    else:
        pass

